template<>struct Wire<UT_MODULE> {static Json Encode(const UT_MODULE& v){Json j=Json::object();j["id"]=EncodeWire(v.id);j["ready"]=EncodeWire(v.ready);j["reserved"]=EncodeWire(v.reserved);j["instance"]=EncodeWire(v.instance);j["description"]=EncodeWire(v.description);return j;}static void Decode(const Json& j,UT_MODULE& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="id")DecodeWire(it.value(),v.id);else if(it.key()=="ready")DecodeWire(it.value(),v.ready);else if(it.key()=="reserved")DecodeWire(it.value(),v.reserved);else if(it.key()=="instance")DecodeWire(it.value(),v.instance);else if(it.key()=="description")DecodeWire(it.value(),v.description);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
